async function check(label,fn){try{const details=await fn();results.push({label,ok:true,details});}catch(e){results.push({label,ok:false,error:e.stack});}}
await check('Repeated activity clicks commit only once, then unlock after cooldown',async()=>{const h=harness();await h.settle();await h.click(h.byClass('game-current-place')[0]);const action=h.byClass('game-do-action')[0];const pending=action.props.onClick();action.props.onClick();await pending;await h.settle();assert.equal(h.apiCalls.length,1);const hours=h.props.g.players[0].hours;assert.equal(hours,5);assert.equal(h.byClass('game-do-action')[0].props.disabled,true);h.advance(650);assert.equal(h.byClass('game-do-action')[0].props.disabled,false);await h.click(h.byClass('game-do-action')[0]);assert.equal(h.apiCalls.length,2);assert.equal(h.props.g.players[0].hours,4);return{initialAction:h.apiCalls[0],hoursAfterSecond:4,events:h.events};});
